//! Test-only writer for synthetic, spec-conformant archives (docs/specs/dat-container.md).
//!
//! It produces archives entirely from generated bytes: no game data is involved. The writer
//! follows the layout rules of the spec (header §3, allocations §4, B-tree §5, compression
//! §6.1, set membership §7.2) and tiles the data area exactly, so a correct reader must
//! read everything back and a correct validator must report no issues.

#![allow(dead_code)]

use std::collections::BTreeMap;
use std::io::Write;

use flate2::Compression;
use flate2::write::ZlibEncoder;

pub const HEADER_LEN: usize = 0x400;
pub const NODE_PAYLOAD: usize = 2452;

/// How a record's bytes are laid out on disk.
#[derive(Clone, Debug)]
pub enum Layout {
    /// One allocation sized by the allocation rule.
    Plain,
    /// One allocation `extra` bytes larger than the rule (a "reused" extent).
    Slack(u32),
    /// First extent sized for `first` payload bytes plus the fragment table, then one
    /// fragment per chunk (the last chunk absorbs whatever remains).
    Fragmented { first: usize, chunks: Vec<usize> },
    /// Legacy tail-first chain with `block_payload` bytes per block (spec §4.3).
    Legacy { block_payload: usize },
}

#[derive(Clone, Debug)]
pub struct Rec {
    pub did: u32,
    pub flags: u16,
    pub stored: Vec<u8>,
    pub layout: Layout,
    pub stamp: u16,
    pub time: u32,
    pub iteration: u32,
}

#[derive(Clone, Debug)]
pub struct Builder {
    pub min_alloc: u32,
    pub engine_version: u32,
    pub dataset: u32,
    pub subset: u32,
    /// Maximum entries per node used when bulk-loading the tree (3..=61).
    pub fanout: usize,
    pub records: Vec<Rec>,
    /// Put a free extent between the nodes and the records.
    pub free_hole: bool,
    /// Set-membership record contents `(set id, part index, part count)`.
    pub membership: Option<([u8; 16], u32, u32)>,
    /// Fill unused pointer/entry slots of nodes with non-zero stale bytes.
    pub stale_garbage: bool,
    /// Extra bytes on every node allocation (reused larger extents).
    pub node_extra: u32,
}

/// Result of [`Builder::build`]: the bytes plus where things were put.
#[derive(Clone, Debug)]
pub struct Built {
    pub bytes: Vec<u8>,
    pub root_index: usize,
    /// `(offset, size)` per node, by node index.
    pub nodes: Vec<(u32, u32)>,
    /// DIDs per node, by node index.
    pub node_dids: Vec<Vec<u32>>,
    /// Child node indices per node.
    pub node_children: Vec<Vec<usize>>,
    /// DID → (first extent offset, allocation size).
    pub records: BTreeMap<u32, (u32, u32)>,
}

impl Built {
    pub fn root(&self) -> (u32, u32) {
        self.nodes[self.root_index]
    }
    /// Absolute position of child pointer `i` of the node at `node_off`.
    pub fn child_ptr_pos(node_off: u32, i: usize) -> usize {
        node_off as usize + 8 + 8 * i
    }
    /// Absolute position of the entry count of the node at `node_off`.
    pub fn count_pos(node_off: u32) -> usize {
        node_off as usize + 8 + 496
    }
    /// Absolute position of entry `i` of the node at `node_off`.
    pub fn entry_pos(node_off: u32, i: usize) -> usize {
        node_off as usize + 8 + 500 + 32 * i
    }
    pub fn put_u32(&mut self, pos: usize, v: u32) {
        self.bytes[pos..pos + 4].copy_from_slice(&v.to_le_bytes());
    }
    pub fn get_u32(&self, pos: usize) -> u32 {
        u32::from_le_bytes(self.bytes[pos..pos + 4].try_into().unwrap())
    }
}

pub fn zlib(raw: &[u8], level: Compression) -> Vec<u8> {
    let mut enc = ZlibEncoder::new(Vec::new(), level);
    enc.write_all(raw).unwrap();
    let z = enc.finish().unwrap();
    let mut out = (raw.len() as u32).to_le_bytes().to_vec();
    out.extend_from_slice(&z);
    out
}

/// Deterministic pseudo-random bytes (xorshift), so tests need no RNG crate.
pub fn noise(seed: u64, len: usize) -> Vec<u8> {
    let mut x = seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1;
    (0..len)
        .map(|_| {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            (x >> 24) as u8
        })
        .collect()
}

/// Bytes that start with the DID echo, like most real record types (spec §6.2).
pub fn payload(did: u32, len: usize) -> Vec<u8> {
    let mut v = did.to_le_bytes().to_vec();
    v.extend(noise(u64::from(did), len.saturating_sub(4)));
    v.truncate(len);
    v
}

fn round4(x: usize) -> usize {
    x.div_ceil(4) * 4
}

struct TNode {
    entries: Vec<usize>,
    children: Vec<usize>,
}

fn cap(h: usize, m: usize) -> usize {
    let mut c: usize = 1;
    for _ in 0..=h {
        c = c.saturating_mul(m + 1);
    }
    c - 1
}

fn build_tree(keys: &[usize], h: usize, m: usize, nodes: &mut Vec<TNode>) -> usize {
    if h == 0 {
        assert!(keys.len() <= m);
        nodes.push(TNode {
            entries: keys.to_vec(),
            children: Vec::new(),
        });
        return nodes.len() - 1;
    }
    let child_cap = cap(h - 1, m);
    // c children hold at most c·child_cap keys plus c − 1 separators.
    let c = (keys.len() + 1).div_ceil(child_cap + 1).max(2);
    assert!(c <= m + 1);
    let total = keys.len() - (c - 1);
    let (base, extra) = (total / c, total % c);
    let mut entries = Vec::new();
    let mut children = Vec::new();
    let mut pos = 0;
    for i in 0..c {
        let k = base + usize::from(i < extra);
        children.push(build_tree(&keys[pos..pos + k], h - 1, m, nodes));
        pos += k;
        if i + 1 < c {
            entries.push(keys[pos]);
            pos += 1;
        }
    }
    nodes.push(TNode { entries, children });
    nodes.len() - 1
}

impl Default for Builder {
    fn default() -> Self {
        Self {
            min_alloc: 0x100,
            engine_version: 112,
            dataset: 0x0103_0000,
            subset: 0,
            fanout: 61,
            records: Vec::new(),
            free_hole: true,
            membership: Some(([0x5A; 16], 0, 1)),
            stale_garbage: true,
            node_extra: 0,
        }
    }
}

impl Builder {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add(&mut self, did: u32, flags: u16, stored: Vec<u8>, layout: Layout) -> &mut Self {
        self.records.push(Rec {
            did,
            flags,
            stored,
            layout,
            stamp: 39,
            time: 1_700_000_000 + did % 1000,
            iteration: did % 7,
        });
        self
    }

    pub fn stored(&mut self, did: u32, data: Vec<u8>) -> &mut Self {
        self.add(did, 2, data, Layout::Plain)
    }

    pub fn compressed(&mut self, did: u32, raw: &[u8], level: Compression) -> &mut Self {
        self.add(did, 3, zlib(raw, level), Layout::Plain)
    }

    pub fn fragmented(
        &mut self,
        did: u32,
        data: Vec<u8>,
        first: usize,
        chunks: Vec<usize>,
    ) -> &mut Self {
        self.add(did, 2, data, Layout::Fragmented { first, chunks })
    }

    pub fn legacy(&mut self, did: u32, data: Vec<u8>, block_payload: usize) -> &mut Self {
        self.add(did, 2, data, Layout::Legacy { block_payload })
    }

    pub fn build(&self) -> Built {
        let min = self.min_alloc as usize;
        let mut recs = self.records.clone();
        if let Some((sid, part, count)) = self.membership {
            let mut m = sid.to_vec();
            m.extend_from_slice(&part.to_le_bytes());
            m.extend_from_slice(&count.to_le_bytes());
            recs.push(Rec {
                did: 0xFFFF_0005,
                flags: 2,
                stored: m,
                layout: Layout::Plain,
                stamp: 1,
                time: 1_700_000_000,
                iteration: 0,
            });
        }
        recs.sort_by_key(|r| r.did);
        for w in recs.windows(2) {
            assert_ne!(w[0].did, w[1].did, "duplicate DID in builder");
        }

        // Tree.
        let m = self.fanout;
        assert!((3..=61).contains(&m));
        let keys: Vec<usize> = (0..recs.len()).collect();
        let mut h = 0;
        while cap(h, m) < keys.len() {
            h += 1;
        }
        let mut tnodes = Vec::new();
        let root_index = build_tree(&keys, h, m, &mut tnodes);

        // Allocation.
        let mut cursor = HEADER_LEN;
        let mut alloc = |size: usize| {
            let o = cursor;
            cursor += size;
            o
        };
        let node_size = min.max(8 + NODE_PAYLOAD) + self.node_extra as usize;
        let node_off: Vec<usize> = tnodes.iter().map(|_| alloc(node_size)).collect();
        let mut free: Vec<(usize, usize)> = Vec::new();
        if self.free_hole {
            let s = min.max(0x200);
            free.push((alloc(s), s));
        }
        struct Placed {
            off: usize,
            size: usize,
            frags: Vec<(usize, usize)>,  // (offset, length)
            blocks: Vec<(usize, usize)>, // legacy (offset, size), incl. first
        }
        let mut placed: Vec<Placed> = recs
            .iter()
            .map(|r| {
                let l = r.stored.len();
                let size = match &r.layout {
                    Layout::Plain => min.max(round4(l + 8)),
                    Layout::Slack(x) => min.max(round4(l + 8)) + *x as usize,
                    Layout::Fragmented { first, chunks } => {
                        min.max(round4(8 + first + 8 * chunks.len()))
                    }
                    Layout::Legacy { block_payload } => 8 + block_payload,
                };
                Placed {
                    off: alloc(size),
                    size,
                    frags: Vec::new(),
                    blocks: Vec::new(),
                }
            })
            .collect();
        for (r, p) in recs.iter().zip(placed.iter_mut()) {
            let l = r.stored.len();
            match &r.layout {
                Layout::Fragmented { chunks, .. } => {
                    let cap1 = p.size - 8 - 8 * chunks.len();
                    let mut remaining = l - l.min(cap1);
                    for (i, &c) in chunks.iter().enumerate() {
                        let c = if i + 1 == chunks.len() {
                            remaining
                        } else {
                            c.min(remaining)
                        };
                        let flen = min.max(round4(c));
                        p.frags.push((alloc(flen), flen));
                        remaining -= remaining.min(flen);
                    }
                }
                Layout::Legacy { block_payload } => {
                    let k = l.div_ceil(*block_payload).max(1);
                    p.blocks.push((p.off, p.size));
                    for _ in 1..k {
                        p.blocks.push((alloc(8 + block_payload), 8 + block_payload));
                    }
                }
                _ => {}
            }
        }
        let free_count = free.len() + 1;
        let table_size = min.max(round4(8 + 8 * free_count + 4));
        let table_off = alloc(table_size);
        let tail = min.max(0x1000);
        free.push((alloc(tail), tail));
        let file_len = cursor;

        // Write.
        let mut b = vec![0u8; file_len];
        let put32 = |b: &mut Vec<u8>, pos: usize, v: u32| {
            b[pos..pos + 4].copy_from_slice(&v.to_le_bytes());
        };
        b[0x100..0x104].copy_from_slice(&[0x00, 0x50, 0x4C, 0x00]);
        put32(&mut b, 0x140, 0x5442);
        put32(&mut b, 0x144, self.min_alloc);
        put32(&mut b, 0x148, file_len as u32);
        put32(&mut b, 0x14C, self.dataset);
        put32(&mut b, 0x150, self.subset);
        put32(&mut b, 0x154, table_off as u32);
        put32(&mut b, 0x15C, free.len() as u32);
        put32(&mut b, 0x160, node_off[root_index] as u32);
        put32(&mut b, 0x174, self.engine_version);
        put32(&mut b, 0x178, 3);
        b[0x17C..0x18C].copy_from_slice(&[0x11; 16]);
        put32(&mut b, 0x18C, 1100);
        put32(&mut b, 0x190, 104);
        put32(&mut b, 0x194, 32);
        put32(&mut b, 0x198, 8);
        put32(
            &mut b,
            0x19C,
            free.iter().map(|&(_, s)| (s - 8) as u32).sum::<u32>(),
        );
        put32(&mut b, 0x1A0, table_size as u32);
        put32(&mut b, 0x1A4, node_size as u32);

        // Free extents hold stale bytes; the table lists them by ascending offset.
        for &(o, s) in &free {
            b[o..o + s].fill(0xEE);
        }
        for (i, &(o, s)) in free.iter().enumerate() {
            put32(&mut b, table_off + 8 + 8 * i, s as u32);
            put32(&mut b, table_off + 8 + 8 * i + 4, o as u32);
        }

        // Nodes.
        for (ni, t) in tnodes.iter().enumerate() {
            let p = node_off[ni] + 8;
            let n = t.entries.len();
            if self.stale_garbage {
                b[p..p + NODE_PAYLOAD].fill(0xA5);
                // Pointers 0..=n must be exact (zero for a leaf).
                b[p..p + 8 * (n + 1)].fill(0);
            } else {
                b[p..p + NODE_PAYLOAD].fill(0);
            }
            b[node_off[ni]..node_off[ni] + 8].fill(0);
            for (ci, &c) in t.children.iter().enumerate() {
                put32(&mut b, p + 8 * ci, node_size as u32);
                put32(&mut b, p + 8 * ci + 4, node_off[c] as u32);
            }
            put32(&mut b, p + 496, n as u32);
            for (ei, &ri) in t.entries.iter().enumerate() {
                let r = &recs[ri];
                let pl = &placed[ri];
                let e = p + 500 + 32 * ei;
                b[e..e + 2].copy_from_slice(&r.flags.to_le_bytes());
                b[e + 2..e + 4].copy_from_slice(&r.stamp.to_le_bytes());
                put32(&mut b, e + 4, r.did);
                put32(&mut b, e + 8, pl.off as u32);
                put32(&mut b, e + 12, r.stored.len() as u32);
                put32(&mut b, e + 16, r.time);
                put32(&mut b, e + 20, r.iteration);
                put32(&mut b, e + 24, pl.size as u32);
                put32(&mut b, e + 28, 0);
            }
        }

        // Records.
        for (r, p) in recs.iter().zip(&placed) {
            let data = &r.stored;
            let l = data.len();
            match &r.layout {
                Layout::Plain | Layout::Slack(_) => {
                    b[p.off + 8..p.off + 8 + l].copy_from_slice(data);
                }
                Layout::Fragmented { .. } => {
                    let f = p.frags.len();
                    put32(&mut b, p.off, f as u32);
                    let cap1 = p.size - 8 - 8 * f;
                    let first = l.min(cap1);
                    b[p.off + 8..p.off + 8 + first].copy_from_slice(&data[..first]);
                    let table = p.off + p.size - 8 * f;
                    let mut pos = first;
                    for (i, &(fo, fl)) in p.frags.iter().enumerate() {
                        put32(&mut b, table + 8 * i, fl as u32);
                        put32(&mut b, table + 8 * i + 4, fo as u32);
                        let take = fl.min(l - pos);
                        b[fo..fo + take].copy_from_slice(&data[pos..pos + take]);
                        pos += take;
                    }
                    assert_eq!(pos, l);
                }
                Layout::Legacy { .. } => {
                    let mut remaining = l;
                    for (j, &(bo, bs)) in p.blocks.iter().enumerate() {
                        let (ns, no) = p.blocks.get(j + 1).map_or((0, 0), |&(o, s)| (s, o));
                        put32(&mut b, bo, ns as u32);
                        put32(&mut b, bo + 4, no as u32);
                        let take = (bs - 8).min(remaining);
                        b[bo + 8..bo + 8 + take]
                            .copy_from_slice(&data[remaining - take..remaining]);
                        remaining -= take;
                    }
                    assert_eq!(remaining, 0);
                }
            }
        }

        Built {
            bytes: b,
            root_index,
            nodes: node_off
                .iter()
                .map(|&o| (o as u32, node_size as u32))
                .collect(),
            node_dids: tnodes
                .iter()
                .map(|t| t.entries.iter().map(|&i| recs[i].did).collect())
                .collect(),
            node_children: tnodes.iter().map(|t| t.children.clone()).collect(),
            records: recs
                .iter()
                .zip(&placed)
                .map(|(r, p)| (r.did, (p.off as u32, p.size as u32)))
                .collect(),
        }
    }
}

/// A unique scratch directory under the system temp dir, removed on drop.
pub struct TempDir(pub std::path::PathBuf);

impl TempDir {
    pub fn new(tag: &str) -> Self {
        use std::sync::atomic::{AtomicU32, Ordering};
        static N: AtomicU32 = AtomicU32::new(0);
        let p = std::env::temp_dir().join(format!(
            "tessera-dat-{tag}-{}-{}",
            std::process::id(),
            N.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = std::fs::remove_dir_all(&p);
        std::fs::create_dir_all(&p).unwrap();
        Self(p)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}
